// Shared engine constants. Single source of truth for PRODUCT_TYPES
// (used by index.js search() filter + geo-coords.js bbox computation).

/**
 * IFC product entity types — concrete IfcProduct subtypes that have geometry
 * and appear as visible objects in 3D scene.
 *
 * Includes:
 * - Structural: WALL, SLAB, MEMBER, COLUMN, BEAM, FOOTING, PILE
 * - Architectural: DOOR, WINDOW, STAIR, RAILING, ROOF, RAMP, COVERING, PLATE,
 *   CURTAINWALL, FURNISHING
 * - Generic: BUILDINGELEMENTPROXY
 * - Reinforcement: REINFORCINGBAR, REINFORCINGMESH, FASTENER, MECHANICALFASTENER, DISCRETEACCESSORY
 *
 * Excludes:
 * - Spatial containers (IFCSITE, IFCBUILDING, IFCBUILDINGSTOREY, IFCSPACE) —
 *   these are NOT geometry-bearing and would skew bbox computation. Search
 *   API filters them via PRODUCT_TYPES_INCLUDING_SPATIAL if app vrstva needs them.
 * - Geometry primitives (CARTESIANPOINT, DIRECTION, etc.)
 * - Property entities (PROPERTYSET, PROPERTYSINGLEVALUE)
 * - Relationships (RELDEFINES*, RELAGGREGATES, etc.)
 */
export const PRODUCT_TYPES = new Set([
  'IFCWALL', 'IFCWALLSTANDARDCASE', 'IFCSLAB', 'IFCMEMBER', 'IFCCOLUMN', 'IFCBEAM',
  'IFCDOOR', 'IFCWINDOW', 'IFCSTAIR', 'IFCRAILING', 'IFCROOF', 'IFCFOOTING',
  'IFCBUILDINGELEMENTPROXY', 'IFCFURNISHINGELEMENT', 'IFCCOVERING', 'IFCPLATE',
  'IFCCURTAINWALL', 'IFCREINFORCINGBAR', 'IFCREINFORCINGMESH', 'IFCDISCRETEACCESSORY',
  'IFCFASTENER', 'IFCMECHANICALFASTENER', 'IFCPILE', 'IFCRAMP',
  // Architectural / structural additions (Revit interiors, Tekla assemblies)
  'IFCFURNITURE', 'IFCSYSTEMFURNITUREELEMENT', 'IFCSTAIRFLIGHT', 'IFCRAMPFLIGHT',
  'IFCBUILDINGELEMENTPART', 'IFCELEMENTASSEMBLY', 'IFCTRANSPORTELEMENT',
  'IFCSHADINGDEVICE', 'IFCCHIMNEY', 'IFCCIVILELEMENT', 'IFCGEOGRAPHICELEMENT',
  'IFCTENDON', 'IFCTENDONANCHOR', 'IFCVIBRATIONISOLATOR',
  // MEP — IFC2x3 generic distribution + IFC4 concrete subtypes (Revit MEP)
  'IFCDISTRIBUTIONELEMENT', 'IFCDISTRIBUTIONFLOWELEMENT', 'IFCDISTRIBUTIONCONTROLELEMENT',
  'IFCDISTRIBUTIONCHAMBERELEMENT', 'IFCENERGYCONVERSIONDEVICE',
  'IFCFLOWSEGMENT', 'IFCFLOWFITTING', 'IFCFLOWTERMINAL', 'IFCFLOWCONTROLLER',
  'IFCFLOWMOVINGDEVICE', 'IFCFLOWSTORAGEDEVICE', 'IFCFLOWTREATMENTDEVICE',
  'IFCDUCTSEGMENT', 'IFCDUCTFITTING', 'IFCDUCTSILENCER', 'IFCPIPESEGMENT', 'IFCPIPEFITTING',
  'IFCCABLECARRIERSEGMENT', 'IFCCABLECARRIERFITTING', 'IFCCABLESEGMENT', 'IFCCABLEFITTING',
  'IFCLIGHTFIXTURE', 'IFCLAMP', 'IFCAIRTERMINAL', 'IFCAIRTERMINALBOX', 'IFCSANITARYTERMINAL',
  'IFCVALVE', 'IFCPUMP', 'IFCFAN', 'IFCCOMPRESSOR', 'IFCBOILER', 'IFCCHILLER', 'IFCCOIL',
  'IFCDAMPER', 'IFCFILTER', 'IFCHEATEXCHANGER', 'IFCHUMIDIFIER', 'IFCTANK',
  'IFCUNITARYEQUIPMENT', 'IFCSPACEHEATER', 'IFCINTERCEPTOR', 'IFCFLOWMETER', 'IFCFLOWINSTRUMENT',
  'IFCELECTRICAPPLIANCE', 'IFCELECTRICDISTRIBUTIONBOARD', 'IFCELECTRICDISTRIBUTIONPOINT',
  'IFCELECTRICFLOWSTORAGEDEVICE', 'IFCELECTRICGENERATOR', 'IFCELECTRICMOTOR',
  'IFCOUTLET', 'IFCSWITCHINGDEVICE', 'IFCJUNCTIONBOX', 'IFCTRANSFORMER',
  'IFCPROTECTIVEDEVICE', 'IFCFIRESUPPRESSIONTERMINAL', 'IFCSENSOR', 'IFCACTUATOR',
  'IFCALARM', 'IFCCONTROLLER', 'IFCUNITARYCONTROLELEMENT',
  'IFCAUDIOVISUALAPPLIANCE', 'IFCCOMMUNICATIONSAPPLIANCE', 'IFCMEDICALDEVICE',
  // IFC4X3 civil/infrastructure products
  'IFCPAVEMENT', 'IFCKERB', 'IFCCOURSE', 'IFCEARTHWORKSFILL', 'IFCREINFORCEDSOIL',
  'IFCRAIL', 'IFCTRACKELEMENT', 'IFCSIGN', 'IFCSIGNAL', 'IFCBEARING',
  'IFCDEEPFOUNDATION', 'IFCCAISSONFOUNDATION', 'IFCMOORINGDEVICE', 'IFCNAVIGATIONELEMENT',
]);

/**
 * Product types that carry geometry but must NOT be rendered as solids:
 * - IFCOPENINGELEMENT / IFCOPENINGSTANDARDCASE / IFCVOIDINGFEATURE — the
 *   IfcFeatureElementSubtraction family: their Body/Reference shape is the
 *   *subtracted* volume (IfcRelVoidsElement). Drawing it paints a solid over
 *   the hole — Tekla exports IfcVoidingFeature drill/cut references that can
 *   dwarf the element itself (31 m circles in D222_SO127401_SKR). Until real
 *   CSG subtraction lands, viewers hide these.
 * - IFCSPACE — room volumes; drawn solid they fill the whole interior and
 *   occlude everything inside (standard viewers hide them by default).
 */
export const HIDDEN_PRODUCT_TYPES = new Set([
  'IFCOPENINGELEMENT', 'IFCOPENINGSTANDARDCASE', 'IFCVOIDINGFEATURE', 'IFCSPACE',
]);

/**
 * Spatial container types — useful for navigation/hierarchy queries
 * (e.g., "list buildings in this model"), NOT included in bbox computation.
 */
export const SPATIAL_CONTAINER_TYPES = new Set([
  'IFCSITE', 'IFCBUILDING', 'IFCBUILDINGSTOREY', 'IFCSPACE',
]);

/**
 * Union: products + spatial containers. Used by search() with no type filter
 * to return all entities visible to app vrstva (3D + tree navigation).
 */
export const PRODUCT_TYPES_INCLUDING_SPATIAL = new Set([
  ...PRODUCT_TYPES,
  ...SPATIAL_CONTAINER_TYPES,
]);
